import { CELL_SIZE } from '../config';
import type { BaseVisualCell } from '../entities/BaseVisuals';
import type { WorldMetrics } from '../world/WorldMetrics';
import { SeededValueNoise } from './SeededValueNoise';
import { groundMaterialPhase } from './GroundMaterialConfig';
import type { GrassHeightMap, GroundMaterialPixels } from './GroundMaterialSamples';
import { nearestStructurePoint, structureBounds } from './StructureOutline';

export interface BaseApronMaterials {
  readonly soil: GroundMaterialPixels;
  readonly gravel: GroundMaterialPixels;
  readonly grassHeight: GrassHeightMap;
}

/**
 * Ground footprint of a base: its cells, or for an outlined structure its world-pixel outline
 * rects. With rects the apron follows the outline instead of the cell squares.
 */
export interface BaseGroundingFootprint {
  readonly cells: readonly BaseVisualCell[];
  readonly rects?: readonly { readonly x: number; readonly y: number; readonly width: number; readonly height: number }[];
}

/** World-pixel raster of one apron; its origin is the top-left world pixel. */
export interface BaseApronRaster {
  readonly worldX: number;
  readonly worldY: number;
  readonly width: number;
  readonly height: number;
}

/**
 * Foundation ground around a base: trodden earth with gravel fines worked in, a few loose stones,
 * a narrow width that wanders from grass right at the plates to a short spill, and a seam that
 * frays into the actual grass blades. Kept quiet: it embeds the plates, it does not frame them.
 * World pixels.
 */
export const BASE_APRON_CONFIG = {
  /** Apron width beyond the footprint, before the edge warp; often none, never a wide ring. */
  minWidthPx: -2,
  maxWidthPx: 16,
  /** Two-dimensional meander of the apron edge. */
  edgeWarpPx: 5,
  /** Density ramp of the outer edge; the grass seam works within it. */
  seamPx: 9,
  /** Highest opacity outside the footprint: the ground below still shows a little. */
  maxCover: 0.9,
  /** Contact shade right at the plates. */
  contactPx: 3,
  contactShade: 0.22,
  /** Earth and gravel fines between the stones: soil with a share of desaturated gravel. */
  finesDesaturate: 0.3,
  finesGain: 0.84,
  finesSoil: 0.55,
  /** Loose stones of the same gravel, few and only a little lighter than the ground. */
  stoneThreshold: 0.62,
  gravelDesaturate: 0.4,
  gravelGain: 0.82,
  /** Loose gravel beyond the apron edge. */
  scatterPx: 5,
  /**
   * On the gravel of a base site the apron is no earth band: only gravel compacted a little
   * darker than the gravel around it, with lower opacity so the site's own surface carries on.
   */
  onGravelTone: 0.88,
  onGravelCover: 0.55,
} as const;

/** Spacing of the coarse lattice on which the ground's gravel coverage is sampled. */
const GRAVEL_COVERAGE_STEP = 4;

/** Maximum visual reach beyond the footprint; no gameplay geometry changes. */
export const BASE_APRON_REACH_PX = Math.ceil(BASE_APRON_CONFIG.maxWidthPx + BASE_APRON_CONFIG.edgeWarpPx * .75
  + BASE_APRON_CONFIG.seamPx * .5 + BASE_APRON_CONFIG.scatterPx);

/** Coordinate-local noise: independent of entity IDs, faction, cell order and peer RNG. */
const APRON_SEED = 0x5ba5e;

const clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v);
const smooth = (v: number): number => {
  const t = clamp01(v);
  return t * t * (3 - 2 * t);
};

/** World raster covering the footprint and the apron's full reach. */
export function getBaseApronRaster(
  footprint: BaseGroundingFootprint,
  metrics: Pick<WorldMetrics, 'offsetX' | 'offsetY'>,
): BaseApronRaster | null {
  const { cells, rects } = footprint;
  const reach = BASE_APRON_REACH_PX;
  if (rects) {
    if (rects.length === 0) return null;
    const bounds = structureBounds(rects);
    const left = Math.floor(bounds.left) - reach, top = Math.floor(bounds.top) - reach;
    return { worldX: left, worldY: top,
      width: Math.ceil(bounds.right) + reach - left, height: Math.ceil(bounds.bottom) + reach - top };
  }
  if (cells.length === 0) return null;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const cell of cells) {
    minX = Math.min(minX, cell.gridX); minY = Math.min(minY, cell.gridY);
    maxX = Math.max(maxX, cell.gridX + 1); maxY = Math.max(maxY, cell.gridY + 1);
  }
  return {
    worldX: metrics.offsetX + minX * CELL_SIZE - reach,
    worldY: metrics.offsetY + minY * CELL_SIZE - reach,
    width: (maxX - minX) * CELL_SIZE + reach * 2,
    height: (maxY - minY) * CELL_SIZE + reach * 2,
  };
}

/**
 * Writes the apron as straight RGBA into `data` (raster width × height). Pure function of the
 * footprint, the World frame, the shared ground materials and the optional gravel coverage of
 * the ground below, so every peer and rebuild draws the same ground. Under the footprint itself
 * the ground stays compacted: a destroyed cell leaves its bare foundation, not grass. Where the
 * ground below is gravel, earth gives way to compacted gravel of the same material.
 */
export function writeBaseApron(
  data: Uint8ClampedArray,
  raster: BaseApronRaster,
  footprint: BaseGroundingFootprint,
  metrics: Pick<WorldMetrics, 'offsetX' | 'offsetY'>,
  materials: BaseApronMaterials,
  /** Overall brightness; hostile bases sit on darker, void-stained ground. */
  brightness = 1,
  /** Gravel opacity of the ground below at a world point (0 grass, 1 gravel); none means grass. */
  gravelCoverage?: (worldX: number, worldY: number) => number,
): void {
  data.fill(0);
  const C = BASE_APRON_CONFIG;
  // The ground's gravel varies smoothly; a coarse lattice keeps the probe off the pixel loop.
  const step = GRAVEL_COVERAGE_STEP;
  const coverageCols = Math.ceil(raster.width / step) + 2, coverageRows = Math.ceil(raster.height / step) + 2;
  const coverage = gravelCoverage ? new Float32Array(coverageCols * coverageRows) : null;
  if (coverage && gravelCoverage) {
    for (let j = 0; j < coverageRows; j++) for (let i = 0; i < coverageCols; i++) {
      coverage[j * coverageCols + i] = gravelCoverage(raster.worldX + i * step, raster.worldY + j * step);
    }
  }
  const lattice = new SeededValueNoise(APRON_SEED);
  const noise = (x: number, y: number, period: number, salt: number) => lattice.sample(x, y, period, salt);
  const { soil, gravel, grassHeight } = materials;
  const { cells, rects } = footprint;
  // Outline rects in the same metrics-relative frame as the pixel loop.
  const outline = rects?.map(rect => ({ x: rect.x - metrics.offsetX, y: rect.y - metrics.offsetY,
    width: rect.width, height: rect.height }));
  // Footprint occupancy on a small grid around the raster, so each pixel tests numbers only.
  // A cell further than this many cells away is beyond the apron's reach from any pixel.
  const ring = Math.ceil(BASE_APRON_REACH_PX / CELL_SIZE);
  const gridLeft = Math.floor((raster.worldX - metrics.offsetX) / CELL_SIZE) - ring;
  const gridTop = Math.floor((raster.worldY - metrics.offsetY) / CELL_SIZE) - ring;
  const gridCols = Math.ceil(raster.width / CELL_SIZE) + ring * 2 + 2;
  const gridRows = Math.ceil(raster.height / CELL_SIZE) + ring * 2 + 2;
  const occupied = new Uint8Array(gridCols * gridRows);
  if (!outline) for (const cell of cells) occupied[(cell.gridY - gridTop) * gridCols + cell.gridX - gridLeft] = 1;
  const reach2 = BASE_APRON_REACH_PX * BASE_APRON_REACH_PX;
  for (let py = 0; py < raster.height; py++) {
    const y = raster.worldY + py + .5 - metrics.offsetY;
    const gy = Math.floor(y / CELL_SIZE);
    const soilRow = groundMaterialPhase(Math.floor(y), soil.height) * soil.width;
    const gravelRow = groundMaterialPhase(Math.floor(y), gravel.height) * gravel.width;
    const heightRow = groundMaterialPhase(Math.floor(y), grassHeight.height) * grassHeight.width;
    for (let px = 0; px < raster.width; px++) {
      const x = raster.worldX + px + .5 - metrics.offsetX;
      const gx = Math.floor(x / CELL_SIZE);
      // Exact distance to the union of footprint squares or outline rects (0 inside).
      let nearest = reach2;
      if (outline) {
        const point = nearestStructurePoint(outline, x, y);
        nearest = Math.min(reach2, point.distance * point.distance);
      } else for (let dy = -ring; dy <= ring && nearest > 0; dy++) {
        const rowStart = (gy + dy - gridTop) * gridCols - gridLeft;
        const top = (gy + dy) * CELL_SIZE;
        const oy = top > y ? top - y : y > top + CELL_SIZE ? y - top - CELL_SIZE : 0;
        for (let dx = -ring; dx <= ring; dx++) {
          if (!occupied[rowStart + gx + dx]) continue;
          const left = (gx + dx) * CELL_SIZE;
          const ox = left > x ? left - x : x > left + CELL_SIZE ? x - left - CELL_SIZE : 0;
          const d2 = ox * ox + oy * oy;
          if (d2 < nearest) nearest = d2;
        }
      }
      if (nearest >= reach2) continue;
      const distance = Math.sqrt(nearest);
      const inside = distance === 0;
      // Fines cover: solid inside, a grass seam at the outer edge driven by the real blade height.
      // Outside, the edge meanders and its width wanders around the perimeter.
      let cover = 1, warped = 0, width = 0;
      if (!inside) {
        warped = distance + (noise(x, y, 17, 1) - .5) * C.edgeWarpPx + (noise(x, y, 6, 2) - .5) * C.edgeWarpPx * .5;
        const wide = smooth(noise(x, y, 71, 3) * .91 + noise(x, y, 29, 4) * .39 - .15);
        width = C.minWidthPx + (C.maxWidthPx - C.minWidthPx) * wide * Math.sqrt(wide);
        const level = .5 + (width - warped) / C.seamPx * .5;
        const blade = grassHeight.data[heightRow + groundMaterialPhase(Math.floor(x), grassHeight.width)] / 255;
        const tuft = noise(x, y, 5, 5) * .45 + noise(x, y, 13, 6) * .55;
        cover = smooth((level - (blade * .5 + tuft * .5)) / .07 + .5) * C.maxCover;
      }
      // Loose stones: dense at the plates, thinning across the apron, a few beyond it.
      const g = (gravelRow + groundMaterialPhase(Math.floor(x), gravel.width)) * 4;
      const gr = gravel.rgba[g], gg = gravel.rgba[g + 1], gb = gravel.rgba[g + 2];
      const luma = (gr * .3 + gg * .59 + gb * .11) / 255;
      const stone = luma * 1.6 - .25 + (noise(x, y, 4, 7) - .5) * .7;
      const across = inside ? 0 : clamp01(warped / Math.max(4, width + C.scatterPx));
      // Stones lie in drifts: broad patches where they gather, plain fines in between.
      const drift = noise(x, y, 23, 8) * .65 + noise(x, y, 9, 10) * .35;
      const threshold = C.stoneThreshold + across * .6 + (.5 - drift) * .9;
      let stoneAlpha = smooth((stone - threshold) / .12 + .5);
      if (!inside && warped > width + C.scatterPx) stoneAlpha = 0;
      // Gravel of the ground below: 0 on grass, 1 on a base site's gravel.
      let onGravel = 0;
      if (coverage) {
        const u = (px + .5) / step, v = (py + .5) / step, i = Math.floor(u), j = Math.floor(v);
        const tx = u - i, ty = v - j, k = j * coverageCols + i;
        const top = coverage[k] + (coverage[k + 1] - coverage[k]) * tx;
        const bottom = coverage[k + coverageCols] + (coverage[k + coverageCols + 1] - coverage[k + coverageCols]) * tx;
        onGravel = clamp01(top + (bottom - top) * ty);
      }
      cover *= 1 + (C.onGravelCover - 1) * onGravel;
      const alpha = stoneAlpha + cover * (1 - stoneAlpha);
      if (alpha <= 0) continue;

      const s = (soilRow + groundMaterialPhase(Math.floor(x), soil.width)) * 4;
      // Fines vary a little in tone along the perimeter; on gravel they are the gravel itself.
      const earthTone = C.finesGain * (.92 + .16 * noise(x, y, 37, 9));
      const tone = earthTone + (C.onGravelTone - earthTone) * onGravel;
      const soilShare = C.finesSoil * (1 - onGravel);
      const grey = luma * 255, stoneDesaturate = C.gravelDesaturate, fineDesaturate = C.finesDesaturate * (1 - onGravel);
      const contact = inside ? 1 - C.contactShade : 1 - C.contactShade * (1 - smooth(distance / C.contactPx));
      const stoneGain = C.gravelGain * stoneAlpha, normalize = contact * brightness / alpha;
      const fineGain = cover * (1 - stoneAlpha) * tone * (1 - soilShare);
      const soilGain = cover * (1 - stoneAlpha) * tone * soilShare;
      const out = (py * raster.width + px) * 4;
      data[out] = ((gr + (grey - gr) * stoneDesaturate) * stoneGain
        + (gr + (grey - gr) * fineDesaturate) * fineGain + soil.rgba[s] * soilGain) * normalize;
      data[out + 1] = ((gg + (grey - gg) * stoneDesaturate) * stoneGain
        + (gg + (grey - gg) * fineDesaturate) * fineGain + soil.rgba[s + 1] * soilGain) * normalize;
      data[out + 2] = ((gb + (grey - gb) * stoneDesaturate) * stoneGain
        + (gb + (grey - gb) * fineDesaturate) * fineGain + soil.rgba[s + 2] * soilGain) * normalize;
      data[out + 3] = Math.round(alpha * 255);
    }
  }
}
