import * as Phaser from 'phaser';

const TEXTURE_KEY = '_ui_rim_glint';
const TEXTURE_W = 96, TEXTURE_H = 12;
/** One idle cycle: a sweep along the upper rim, a pause, a sweep back along the lower rim, a pause. */
const IDLE_CYCLE_MS = 6400;
const IDLE_SWEEP = 0.24;
const IDLE_ALPHA = 0.5;
const CONFIRM_MS = 340;

/** Rim line of a framed button, relative to the button's centre. */
export interface RimGlintPath { readonly top: number; readonly bottom: number; readonly halfWidth: number }

/**
 * A soft warm highlight that travels along the bronze rim of a framed button.
 * Idle: one calm sweep along the upper rim, later one back along the lower rim.
 * Confirm: both rims at once, fast and brighter. A single additive image; no filters.
 */
export class RimGlint {
  private readonly top: Phaser.GameObjects.Image;
  private readonly bottom: Phaser.GameObjects.Image;
  private idle: Phaser.Tweens.Tween | null = null;
  private confirm: Phaser.Tweens.Tween | null = null;

  constructor(private readonly scene: Phaser.Scene, parent: Phaser.GameObjects.Container,
    private readonly path: RimGlintPath) {
    ensureGlintTexture(scene);
    const make = (y: number) => scene.add.image(0, y, TEXTURE_KEY).setBlendMode(Phaser.BlendModes.ADD)
      .setAlpha(0).setScrollFactor(0);
    this.top = make(path.top);
    this.bottom = make(path.bottom);
    parent.add([this.top, this.bottom]);
  }

  /** Calm idle sweeps until stopped. Idempotent. */
  start(): void {
    if (this.idle) return;
    this.idle = this.scene.tweens.addCounter({ from: 0, to: 1, duration: IDLE_CYCLE_MS, repeat: -1,
      onUpdate: (tween) => {
        if (this.confirm) return;
        const phase = tween.getValue() ?? 0;
        this.place(this.top, phase / IDLE_SWEEP, 1, IDLE_ALPHA);
        this.place(this.bottom, (phase - 0.5) / IDLE_SWEEP, -1, IDLE_ALPHA);
      } });
  }

  stop(): void {
    this.idle?.remove();
    this.idle = null;
    if (!this.confirm) this.hide();
  }

  /** A short bright run along both rims, e.g. when the player confirms. */
  flash(): void {
    this.confirm?.remove();
    this.confirm = this.scene.tweens.addCounter({ from: 0, to: 1, duration: CONFIRM_MS, ease: 'Sine.easeOut',
      onUpdate: (tween) => {
        const t = tween.getValue() ?? 0;
        this.place(this.top, t, 1, 0.95);
        this.place(this.bottom, t, -1, 0.95);
      },
      onComplete: () => { this.confirm = null; this.hide(); } });
  }

  destroy(): void {
    this.idle?.remove();
    this.confirm?.remove();
    this.idle = this.confirm = null;
    this.top.destroy();
    this.bottom.destroy();
  }

  private hide(): void {
    this.top.setAlpha(0);
    this.bottom.setAlpha(0);
  }

  /** `t` 0..1 travels the rim in `direction`; outside that range the glint is hidden. */
  private place(image: Phaser.GameObjects.Image, t: number, direction: 1 | -1, peak: number): void {
    if (t <= 0 || t >= 1) { image.setAlpha(0); return; }
    const eased = 0.5 - Math.cos(Math.PI * t) / 2;
    image.setX(direction * (eased * 2 - 1) * this.path.halfWidth).setAlpha(Math.sin(Math.PI * t) * peak);
  }
}

function ensureGlintTexture(scene: Phaser.Scene): void {
  if (scene.textures.exists(TEXTURE_KEY)) return;
  const texture = scene.textures.createCanvas(TEXTURE_KEY, TEXTURE_W, TEXTURE_H)!;
  const ctx = texture.context;
  ctx.save();
  ctx.translate(TEXTURE_W / 2, TEXTURE_H / 2);
  ctx.scale(TEXTURE_W / TEXTURE_H, 1);
  const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, TEXTURE_H / 2);
  glow.addColorStop(0, 'rgba(255,238,196,1)');
  glow.addColorStop(0.35, 'rgba(240,200,128,.55)');
  glow.addColorStop(1, 'rgba(232,193,112,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(-TEXTURE_H / 2, -TEXTURE_H / 2, TEXTURE_H, TEXTURE_H);
  ctx.restore();
  texture.refresh();
}
