import type { EnemyMeshData } from '../assets/EnemyMeshAssets';
import type { MeshDisplayPose } from './CharacterMeshModel';
import { extendMeshBounds, meshShadowSoftness } from './CharacterMeshModel';
import { TURRET_DECK_PEDESTAL } from './ShadowTurretCasters';

export const ENEMY_SHADOW_CAPACITY = 512;
export const ENEMY_SHADOW_COLUMNS = 32;
export const ENEMY_SHADOW_DEPTH = 9.92;
/** Mounted casters (turrets): above ground and structure decks (ROCKS + .04), below turret aura and sprite (ROCKS + .1/.2). */
export const MOUNTED_SHADOW_DEPTH = 9.09;
export const ENEMY_SHADOW_PAD = 5;

/**
 * No extra jump translation: source positions already contain the attack root's Z. A
 * presentation-only lift (`liftScale`, the hop's growth towards the camera) is divided back out,
 * so the shadow keeps the ground size of the body.
 */
export function enemyMeshMatrix(sprite: MeshDisplayPose, canvas: number, out: Float32Array, liftScale = 1): void {
  const c = Math.cos(sprite.rotation), s = Math.sin(sprite.rotation);
  const sx = sprite.scaleX * sprite.frame.realWidth / canvas * (sprite.flipX ? -1 : 1) / liftScale;
  const sy = sprite.scaleY * sprite.frame.realHeight / canvas * (sprite.flipY ? -1 : 1) / liftScale;
  const px = (.5 - sprite.originX) * sprite.displayWidth / liftScale, py = (.5 - sprite.originY) * sprite.displayHeight / liftScale;
  out.fill(0); out[0] = c * sx; out[1] = s * sx; out[4] = -s * sy; out[5] = c * sy;
  out[10] = Math.sqrt(Math.abs(sx * sy)); out[12] = sprite.x + c * px - s * py;
  out[13] = sprite.y + s * px + c * py; out[15] = 1;
}
export function enemyMeshPose(frame: string | number, data: EnemyMeshData): number {
  if (frame === '__BASE') return 0;
  const pose = Number(frame);
  return Number.isInteger(pose) && data.asset.mesh.poseIndices.includes(pose) ? pose : -1;
}
/**
 * Conservative all-pose bounds also enclose contacts and a deck pedestal of `pedestal` px half side (its square
 * keeps to the grid while the mesh turns). Includes a five-texel transparent gutter.
 */
export function enemyShadowBounds(data: EnemyMeshData, matrix: Float32Array, sun: readonly number[], tileSize: number, out: number[],
  pedestal = 0): void {
  out[0] = out[1] = Infinity; out[2] = out[3] = -Infinity;
  extendMeshBounds(out, data.asset.mesh, matrix, sun);
  if (pedestal > 0) {
    // A turned box of the same half side covers the grid-aligned square.
    const s = pedestal / matrix[10], top = TURRET_DECK_PEDESTAL.topPx / matrix[10];
    extendMeshBounds(out, { bounds: { min: [-s, -s, 0], max: [s, s, top] } }, matrix, sun);
  }
  const w = Math.max(1, out[2] - out[0]) + 6 * matrix[10], h = Math.max(1, out[3] - out[1]) + 6 * matrix[10];
  const pad = ENEMY_SHADOW_PAD / (tileSize - ENEMY_SHADOW_PAD * 2);
  const kernelPad = meshShadowSoftness(matrix[10], sun[2]) * 4 + 1;
  const px = Math.max(w * pad, kernelPad), py = Math.max(h * pad, kernelPad);
  out[0] -= px + 3 * matrix[10]; out[1] -= py + 3 * matrix[10];
  out[2] = w + 2 * px; out[3] = h + 2 * py;
}
