import * as Phaser from 'phaser';
import { CHARACTER_MESH_BLUR } from '../../effects/characterMeshShaders';
import { meshShadowOpacity, meshShadowSoftness } from '../../effects/CharacterMeshModel';
import { CHARACTER_SHADOW_CONFIG, STRUCTURE_SHADOW } from '../../effects/ShadowConfig';
import { createVisibleWorldView, getVisibleWorldView } from '../../graphics/CameraWorldView';
import type { LongCasterFrame } from '../../effects/ShadowSystem';
import { setCloudUniforms, type SunCloudState } from '../../effects/sunlight/cloudShadow';
import { ownSunShader, sunShaderName, SunRenderTarget } from '../../effects/sunlight/SunRenderTarget';
import { STRUCTURE_SHADOW_COMPOSITE_FRAGMENT, STRUCTURE_SHADOW_MASK_FRAGMENT } from './lobbyStructureShaders';

/** Programs shared by every structure; each layer sets its uniforms per draw. */
const MASK_PROGRAM = 'StructureShadowMask', BLUR_PROGRAM = 'StructureShadowBlur', COMPOSITE_PROGRAM = 'StructureShadowComposite';
/** Bearing (direction components) and length changes below these keep the mask: the sun creeps. */
const CAST_EPSILON = .002, LENGTH_EPSILON = .004;
const NO_MOUNTED = new Float32Array([0, 0, 0]);

export interface StructureShadowCanvas {
  /** Canvas top-left in world px and its square size. */
  readonly left: number;
  readonly top: number;
  readonly size: number;
  readonly heightPx: { readonly min: number; readonly max: number };
  readonly caster: Phaser.Textures.Texture;
}

/**
 * Ground shadow of one Blender structure, drawn like a figure's: the caster-height march renders a
 * world-px mask only when the sun has moved on or the mounted turrets turned, a separable Gaussian
 * softens it isotropically, and the per-frame composite applies the figures' opacity, colour and
 * cloud transmission.
 */
export class StructureShadowLayer {
  private readonly mask: SunRenderTarget;
  private readonly horizontal: SunRenderTarget;
  private readonly blurred: SunRenderTarget;
  private readonly composite: Phaser.GameObjects.Shader;
  private readonly texels: number;
  private readonly quad: Float32Array;
  private readonly targetSize: number;
  private readonly canvasUniform: Float32Array;
  private readonly heightUniform: Float32Array;
  private readonly castUniform = new Float32Array(4);
  private readonly horizontalStep = new Float32Array(2);
  private readonly verticalStep = new Float32Array(2);
  private mountedUniform: Float32Array = NO_MOUNTED;
  private clouds: SunCloudState | undefined;
  private opacity = 0;
  private valid = false;
  private lastTexture: WebGLTexture | null | undefined;
  private readonly view = createVisibleWorldView();

  constructor(private readonly scene: Phaser.Scene, canvas: StructureShadowCanvas) {
    const reach = STRUCTURE_SHADOW.maxReachPx;
    const quadSize = canvas.size + reach * 2;
    this.quad = new Float32Array([canvas.left - reach, canvas.top - reach, quadSize, quadSize]);
    this.targetSize = Math.ceil(quadSize * STRUCTURE_SHADOW.maskScale);
    this.canvasUniform = new Float32Array([canvas.left, canvas.top, canvas.size, 0]);
    this.heightUniform = new Float32Array([canvas.heightPx.min, canvas.heightPx.max]);
    this.texels = canvas.caster.source[0].width;
    this.mask = new SunRenderTarget(scene, 'StructureShadowMask', STRUCTURE_SHADOW_MASK_FRAGMENT, set => {
      set('uCaster', 0); set('uMountedCaster', 1); set('uMounted', this.mountedUniform);
      set('uTexels', this.texels); set('uCanvas', this.canvasUniform); set('uHeight', this.heightUniform);
      set('uQuad', this.quad); set('uCast', this.castUniform); set('uSoft', STRUCTURE_SHADOW.endSoftnessPx);
    }, [canvas.caster, scene.textures.get('__DEFAULT')], MASK_PROGRAM);
    this.horizontal = new SunRenderTarget(scene, 'StructureShadowBlurH', CHARACTER_MESH_BLUR,
      set => { set('uMask', 0); set('uStep', this.horizontalStep); }, [this.mask.shader.texture!], BLUR_PROGRAM);
    this.blurred = new SunRenderTarget(scene, 'StructureShadowBlurV', CHARACTER_MESH_BLUR,
      set => { set('uMask', 0); set('uStep', this.verticalStep); }, [this.horizontal.shader.texture!], BLUR_PROGRAM);
    this.composite = new Phaser.GameObjects.Shader(scene, { name: sunShaderName('StructureShadowDisplay'), shaderName: COMPOSITE_PROGRAM,
      fragmentSource: STRUCTURE_SHADOW_COMPOSITE_FRAGMENT, setupUniforms: (set: (name: string, value: unknown) => void) => {
        set('uMask', 0); set('uQuad', this.quad); set('uOpacity', this.opacity); setCloudUniforms(set, this.clouds);
      } }, this.quad[0], this.quad[1], quadSize, quadSize, [this.blurred.shader.texture!]);
    ownSunShader(this.composite, COMPOSITE_PROGRAM, true);
    scene.add.existing(this.composite).setOrigin(0).setDepth(STRUCTURE_SHADOW.layerDepth)
      .setBlendMode(Phaser.BlendModes.MULTIPLY).setVisible(false);
  }

  /** Turrets standing on the structure: their heights above `uniform[0]` (deck px) rise into its shadow. */
  setMounted(texture: Phaser.Textures.Texture, uniform: Float32Array): void {
    this.mask.shader.textures[1] = texture;
    this.mountedUniform = uniform;
    this.valid = false;
  }

  /**
   * Per frame. `fade` (0..1) scales the shadow with a fading structure; `mountedChanged` redraws
   * the mask for turned turrets.
   */
  update(frame: LongCasterFrame, clouds: SunCloudState | undefined, fade: number, visible: boolean, mountedChanged = false): void {
    const path = clouds?.sunPath;
    this.clouds = clouds;
    this.opacity = (path ? meshShadowOpacity(path.strength, path.elevation) : CHARACTER_SHADOW_CONFIG.directOpacity * frame.opacityMult) * fade;
    const shown = visible && frame.visible && this.opacity > .002;
    this.composite.setVisible(shown);
    if (!shown) return;
    // Mounted turrets may stand taller than the structure's own height range.
    const tallest = Math.max(this.heightUniform[1], this.mountedUniform[0] + this.mountedUniform[1]);
    const cast = this.castUniform, reach = Math.min(STRUCTURE_SHADOW.maxReachPx, tallest * frame.lengthMult);
    const moved = Math.abs(cast[0] - frame.x) > CAST_EPSILON || Math.abs(cast[1] - frame.y) > CAST_EPSILON
      || Math.abs(cast[2] - frame.lengthMult) > LENGTH_EPSILON * Math.max(1, frame.lengthMult);
    // A map's forts share the sun: off-camera masks wait until they come into view.
    const view = getVisibleWorldView(this.scene.cameras.main, this.view), q = this.quad;
    if (q[0] > view.right || q[1] > view.bottom || q[0] + q[2] < view.x || q[1] + q[3] < view.y) {
      if (moved || mountedChanged) this.valid = false;
      return;
    }
    const texture = this.mask.shader.glTexture?.webGLTexture;
    if (this.valid && !moved && !mountedChanged && texture === this.lastTexture) return;
    cast[0] = frame.x; cast[1] = frame.y; cast[2] = frame.lengthMult; cast[3] = reach;
    const step = meshShadowSoftness(1, path?.sun[2] ?? Math.SQRT1_2) * STRUCTURE_SHADOW.penumbraScale / this.quad[2];
    this.horizontalStep[0] = step; this.verticalStep[1] = step;
    // A target replaces its texture when it is first sized: every reader takes the current one.
    this.mask.draw(this.targetSize, this.targetSize);
    this.horizontal.shader.textures[0] = this.mask.shader.texture!;
    this.horizontal.draw(this.targetSize, this.targetSize);
    this.blurred.shader.textures[0] = this.horizontal.shader.texture!;
    this.blurred.draw(this.targetSize, this.targetSize);
    this.composite.textures[0] = this.blurred.shader.texture!;
    this.lastTexture = this.mask.shader.glTexture?.webGLTexture;
    this.valid = true;
  }

  destroy(): void {
    this.composite.destroy();
    this.blurred.destroy(); this.horizontal.destroy(); this.mask.destroy();
  }
}
