import * as Phaser from 'phaser';
import type { EnemyVisualSource } from '../../entities/EnemyVisualSource';
import type { InfernoColossusAction } from '../../systems/InfernoColossusState';
import type { EnemyLandingMark } from '../EnemyClawRenderer';
import type { LocalDistortionComposer } from '../distortion/LocalDistortionComposer';
import type { GpuVfxSystem } from '../gpu/GpuVfxSystem';
import type { LightingSystem } from '../LightingSystem';
import { InfernoColossusGlowPresentation } from './InfernoColossusGlowPresentation';
import { InfernoColossusHeatEffects, type FlameStreamSource } from './InfernoColossusHeatEffects';

export type InfernoColossusMarkSink = (id: string, mark: EnemyLandingMark | null, now: number, visible: boolean) => void;

/** A zone lingers briefly after its hit so the hit reads. */
const IMPACT_LINGER_MS = 80;

/**
 * Red danger zones of the Flammenkoloss's big actions in the shared enemy danger family: the
 * shockwave of the phase change and the Glutstoss around the body and the storm flight's landing.
 * The Brandsatz shells are replicated strikes from their windup on; the mortar-strike renderer marks
 * them. Each zone fills from its centre up to the hit. It also draws the body's ember glow. It only observes the
 * replicated phase, volley and action timeline.
 */
export class InfernoColossusPresentation {
  private enemies: () => readonly EnemyVisualSource[] = () => [];
  private clock: () => number = () => this.scene.time.now;
  private markSink: InfernoColossusMarkSink | null = null;
  private readonly sunk = new Set<string>();
  private readonly glow: InfernoColossusGlowPresentation;
  private readonly heat = new InfernoColossusHeatEffects();

  constructor(private readonly scene: Phaser.Scene) {
    this.glow = new InfernoColossusGlowPresentation(scene);
    this.glow.setHeatEffects(this.heat);
    scene.events.on(Phaser.Scenes.Events.PRE_RENDER, this.render, this);
  }

  /** Light map for the mandibles' halo and the lantern's heartbeat. */
  setLightingSystem(lighting: LightingSystem | null): void { this.heat.setLightingSystem(lighting); }
  /** GPU haze rising off the burning mandibles. */
  setGpuVfx(gpu: GpuVfxSystem | null): void { this.heat.setGpuVfx(gpu); }
  /** Heat shimmer over the burning mandibles. */
  setDistortionComposer(composer: LocalDistortionComposer | null): void { this.heat.setDistortionComposer(composer); }
  /** The jets' flames, so the mandible haze flies where they fly. */
  setFlameStreams(streams: FlameStreamSource | null): void { this.heat.setFlameStreams(streams); }

  setEnemySource(source: () => readonly EnemyVisualSource[]): void { this.enemies = source; }
  /** Host-synchronised time: action timestamps are host timestamps. */
  setClock(clock: () => number): void { this.clock = clock; }
  setMarkSink(sink: InfernoColossusMarkSink | null): void { this.markSink = sink; }

  clear(): void {
    const now = this.clock();
    for (const id of this.sunk) this.markSink?.(id, null, now, false);
    this.sunk.clear();
    this.glow.clear();
  }

  destroy(): void {
    this.scene.events.off(Phaser.Scenes.Events.PRE_RENDER, this.render, this);
    this.clear();
    this.heat.destroy();
  }

  private render(): void {
    const now = this.clock(), enemies = this.enemies();
    this.glow.render(enemies, now);
    for (const enemy of enemies) {
      const action = enemy.faction === 'hostile' && enemy.sprite.active ? enemy.getInfernoColossusState?.().action ?? null : null;
      const mark = action ? zoneOf(enemy.id, action, now) : null;
      if (!mark) {
        if (this.sunk.delete(enemy.id)) this.markSink?.(enemy.id, null, now, false);
        continue;
      }
      this.sunk.add(enemy.id);
      this.markSink?.(enemy.id, mark, now, enemy.sprite.visible || action!.kind === 'flight');
    }
  }
}

/** The zone an action shows at `now`, or null outside its warning. */
export function zoneOf(enemyId: string, action: InfernoColossusAction, now: number): EnemyLandingMark | null {
  if (action.radius <= 0 || action.kind === 'siege' || action.kind === 'incendiary' || now < action.markAt) return null;
  if (now > action.commitAt + IMPACT_LINGER_MS) return null;
  return { attackId: `colossus:${enemyId}:${action.kind}:${action.startedAt}`, x: action.x, y: action.y,
    radius: action.radius, startedAt: action.markAt, hitAt: action.commitAt };
}
