import type * as Phaser from 'phaser';
import { enemyEmissionTextureKey } from '../config/enemyEmission';
import { getWalkingSheetForStaticTexture, registerBadgerAnimations } from './BadgerAnimations';

/** Sheets already requested per scene, so a body seen every frame queues its load once. */
const requested = new WeakMap<Phaser.Scene, Set<string>>();

/**
 * The sheet a phased boss shows from its second phase on (the colossus's opened carapace) is large and
 * needed on one map only, so no round preloads it: it loads once that boss appears, while its intro
 * and first phase run. Until it is there the body keeps its first sheet; gameplay never waits for it.
 */
export function ensureBossPhaseSheet(scene: Phaser.Scene, staticImageKey: string): void {
  const sheet = getWalkingSheetForStaticTexture(staticImageKey);
  if (!sheet || scene.textures.exists(sheet.textureKey)) return;
  const keys = requested.get(scene) ?? new Set<string>();
  requested.set(scene, keys);
  if (keys.has(sheet.textureKey)) return;
  keys.add(sheet.textureKey);
  const layout = { frameWidth: sheet.frameWidth, frameHeight: sheet.frameHeight, margin: sheet.margin, spacing: sheet.spacing,
    endFrame: sheet.frameCount - 1 };
  scene.load.spritesheet(sheet.textureKey, sheet.assetPath, layout);
  if (sheet.emissionPath) {
    scene.load.spritesheet(enemyEmissionTextureKey(sheet.textureKey), sheet.emissionPath, { ...layout, ...sheet.emissionLayout });
  }
  scene.load.once('complete', () => {
    // A failed download may be requested again by the next body.
    if (!scene.textures.exists(sheet.textureKey)) keys.delete(sheet.textureKey);
    registerBadgerAnimations(scene.anims, key => scene.textures.exists(key));
  });
  if (!scene.load.isLoading()) scene.load.start();
}
