import { getPipelineAsset, pipelineAnimationKey, type PipelineAsset } from './pipelineAssets';
import type * as Phaser from 'phaser';
import type { TurretWeaponId } from '../types';
import emissionManifest from '../assets/manifests/turret-emission.json';

/**
 * Emission sheets derived from the selected turret builds (scripts/asset-pipeline/turret-emission.mjs): the glowing
 * parts of every beauty frame, same layout, RGB hue and alpha intensity. Only an entry of the live revision counts.
 */
const EMISSION = emissionManifest.assets as Readonly<Record<string, { readonly revision: string; readonly sheet: string; readonly color: string }>>;

/** Texture key of a turret's emission sheet, or null while its live revision has none. */
export function turretEmissionKey(asset: PipelineAsset): string | null {
  return EMISSION[asset.id]?.revision === asset.revision ? `${asset.sheetTextureKey}_emission` : null;
}

/** Colour of a turret's glow, the intensity-weighted hue of its emission sheet. */
export function turretEmissionColor(asset: PipelineAsset): number | null {
  const entry = EMISSION[asset.id];
  return entry?.revision === asset.revision ? parseInt(entry.color.slice(1), 16) : null;
}

export interface TurretVisualSpec {
  readonly textureKey: string;
  readonly asset: PipelineAsset;
  readonly assetPath: string | null;
  readonly displaySize: number;
  /** Source sprites point east, matching Phaser's zero-radian aim direction. */
  readonly rotationOffset: number;
  /** Pixel correction that moves the visible artwork onto the logical turret center. */
  readonly centerCorrectionX: number;
  readonly centerCorrectionY: number;
}

export interface TurretVisualTransform {
  readonly x: number;
  readonly y: number;
  readonly rotation: number;
}

function selected(id: string): TurretVisualSpec {
  const asset = getPipelineAsset(id);
  return Object.freeze({
    textureKey: asset.textureKey,
    asset,
    assetPath: asset.idlePath,
    displaySize: id === 'spore' ? 32 : 40,
    rotationOffset: 0,
    centerCorrectionX: 0,
    centerCorrectionY: 0,
  });
}
const SPORE_VISUAL = selected('spore');
const ROCKET_VISUAL = selected('rocket');
const MACHINE_GUN_VISUAL = selected('machine-gun');
const FLAME_VISUAL = selected('flame');
const VOID_FLAME_VISUAL = selected('void-flame');
const TESLA_VISUAL = selected('tesla');
const GRAVITY_VISUAL = selected('gravity');
const SLOW_BUBBLE_VISUAL = selected('slow-bubble');
const PLASMA_VISUAL = selected('plasma');

export const TURRET_VISUALS: Readonly<Record<TurretWeaponId, TurretVisualSpec>> = Object.freeze({
  SPORES: SPORE_VISUAL,
  BASE_SPORES: SPORE_VISUAL,
  TURRET_SPORES: SPORE_VISUAL,
  SPORE_TURRET_PLASMA: PLASMA_VISUAL,
  TURRET_ROCKET_BURST: ROCKET_VISUAL,
  TURRET_MG: MACHINE_GUN_VISUAL,
  TURRET_FLAME: FLAME_VISUAL,
  TURRET_VOID_FLAME: VOID_FLAME_VISUAL,
  TURRET_TESLA: TESLA_VISUAL,
  TURRET_GRAVITY: GRAVITY_VISUAL,
  TURRET_SLOW_BUBBLE: SLOW_BUBBLE_VISUAL,
});

export function getTurretVisualSpec(weaponId: TurretWeaponId): TurretVisualSpec {
  return TURRET_VISUALS[weaponId];
}

/** Resolves a transform that keeps visible turret artwork on its logical point. */
export function getTurretVisualTransform(
  spec: TurretVisualSpec,
  x: number,
  y: number,
  angle: number,
): TurretVisualTransform {
  const rotation = angle + spec.rotationOffset;
  const cos = Math.cos(rotation);
  const sin = Math.sin(rotation);
  return {
    x: x + cos * spec.centerCorrectionX - sin * spec.centerCorrectionY,
    y: y + sin * spec.centerCorrectionX + cos * spec.centerCorrectionY,
    rotation,
  };
}

export function preloadTurretVisualAssets(loader: Phaser.Loader.LoaderPlugin, additionalAssets: readonly PipelineAsset[] = []): void {
  preloadPipelineSheetAssets(loader, [...Object.values(TURRET_VISUALS).filter(spec => spec.assetPath).map(spec => spec.asset), ...additionalAssets]);
}

/** Idle image, sheet and optional emission sheet of turret-shaped pipeline props. */
export function preloadPipelineSheetAssets(loader: Pick<Phaser.Loader.LoaderPlugin, 'image' | 'spritesheet'>,
  assets: readonly PipelineAsset[]): void {
  const loaded = new Set<string>();
  for (const asset of assets) {
    if (loaded.has(asset.textureKey)) continue;
    loaded.add(asset.textureKey);
    loader.image(asset.textureKey, asset.idlePath);
    loader.spritesheet(asset.sheetTextureKey, asset.sheetPath, {
      frameWidth: asset.layout.frameWidth,
      frameHeight: asset.layout.frameHeight,
      margin: asset.layout.margin,
      spacing: asset.layout.spacing,
      endFrame: asset.layout.frameCount - 1,
    });
    const emission = turretEmissionKey(asset);
    if (emission) loader.spritesheet(emission, EMISSION[asset.id].sheet, {
      frameWidth: asset.layout.frameWidth,
      frameHeight: asset.layout.frameHeight,
      margin: asset.layout.margin,
      spacing: asset.layout.spacing,
      endFrame: asset.layout.frameCount - 1,
    });
  }
}

/** Sheets that are not loaded yet (`isLoaded`) are skipped and registered by a later call. */
export function registerTurretAnimations(anims: Phaser.Animations.AnimationManager, additionalAssets: readonly PipelineAsset[] = [],
  isLoaded: (textureKey: string) => boolean = () => true): void {
  for (const asset of new Set([...Object.values(TURRET_VISUALS).map(spec => spec.asset), ...additionalAssets])) {
    if (!isLoaded(asset.sheetTextureKey)) continue;
    for (const clip of asset.clips) {
      const key = pipelineAnimationKey(asset, clip);
      if (anims.exists(key)) continue;
      const frames = anims.generateFrameNumbers(asset.sheetTextureKey, { frames: clip.frames });
      if (frames.length === 0) continue;
      anims.create({ key, frames,
        frameRate: clip.frameRate, repeat: clip.loop ? -1 : 0,
      });
    }
  }
}
