/**
 * Einziger Auswahlpunkt der Plattform-Implementierung. `__DISTRIBUTION__` ist ein Build-Define,
 * daher entfällt die jeweils andere Implementierung aus dem Bundle.
 */
import { FULL_CONTENT_POLICY } from '../config/distributionContentPolicy';
import type { PlatformServices } from './PlatformServices';
import { steamPlatformServices } from './steam/SteamPlatformServices';
import { webPlatformServices } from './web/WebPlatformServices';

const distributionServices: PlatformServices = __DISTRIBUTION__ === 'steam' ? steamPlatformServices : webPlatformServices;

/**
 * Dev-Server, Tests und Performance-Lab sind keine Distribution: Sie behalten den vollen Inhalt,
 * damit Steam-only-Inhalte entwickelt und gemessen werden können. Ausgelieferte Builds
 * (`npm run build`, `npm run build:steam`) verwenden genau die Policy ihrer Variante.
 */
export const platform: PlatformServices = import.meta.env.DEV || __PERFORMANCE_LAB__
  ? { ...distributionServices, content: FULL_CONTENT_POLICY }
  : distributionServices;

export type {
  PlatformIdentity,
  PlatformInvites,
  PlatformServices,
  PlatformSessions,
} from './PlatformServices';
