import type * as Phaser from 'phaser';
import { MOTION } from './uiTheme';

/** Few pixels: the popup settles onto its anchor instead of sliding in from elsewhere. */
const POPUP_DROP = 6;

/**
 * Shared appearance of small lobby popups: fade in while settling a few pixels downward.
 * Only `alpha` and `y`; popup children sit on absolute coordinates, so a scale would pull them
 * toward the container origin. Closing stays immediate so a click never lands on a fading ghost.
 */
export function playPopupEntrance(scene: Phaser.Scene, container: Phaser.GameObjects.Container): void {
  scene.tweens.killTweensOf(container);
  const y = container.y;
  container.setAlpha(0).setY(y - POPUP_DROP);
  scene.tweens.add({ targets: container, alpha: 1, y, duration: MOTION.base, ease: MOTION.ease.out });
}
