import type { InfernoColossusConfig } from '../config/infernoColossus';
import type { InfernoColossusActionKind } from './InfernoColossusState';

/** Deterministic host random in [0, 1) from a seed (mulberry32). */
export function colossusRandom(seed: number): () => number {
  let t = seed >>> 0;
  return () => {
    t = (t + 0x6d2b79f5) >>> 0;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

export interface ColossusActionInput {
  readonly phase: number;
  readonly now: number;
  /** Earliest start per action (cooldowns, the gap after the last action, phase-two delays). */
  readonly readyAt: Readonly<Record<Exclude<InfernoColossusActionKind, 'transition'>, number>>;
  /** A player, decoy, base surface or construction inside the Glutstoss trigger radius. */
  readonly threatInGlutstossRadius: boolean;
  /** Distance to the hunted target, null without a visible target. */
  readonly huntedDistancePx: number | null;
  /** The body has no walkable route to its target. */
  readonly routeUnreachable: boolean;
  /** At least one player or structure inside the siege range. */
  readonly siegeHasTarget: boolean;
  /** At least one player or decoy inside the beetle salvo's range. */
  readonly salvoHasTarget: boolean;
}

/**
 * Next action, by priority: a close threat is blasted away, a far target is closed by flight,
 * then the siege, then the Brandsatz against a target at range, and last the light beetle salvo.
 * Phase-two actions only from phase 2.
 */
export function chooseColossusAction(input: ColossusActionInput, config: InfernoColossusConfig): Exclude<InfernoColossusActionKind, 'transition'> | null {
  const ready = (kind: keyof ColossusActionInput['readyAt']) => input.now >= input.readyAt[kind];
  const distance = input.huntedDistancePx;
  if (ready('glutstoss') && input.threatInGlutstossRadius) return 'glutstoss';
  if (input.phase >= 2 && ready('flight') && distance !== null && distance <= config.stormFlight.maxRangePx
    && (distance >= config.stormFlight.minRangePx || input.routeUnreachable)) return 'flight';
  if (input.phase >= 2 && ready('siege') && input.siegeHasTarget) return 'siege';
  if (ready('incendiary') && distance !== null && distance >= config.incendiary.minRangePx
    && distance <= config.incendiary.maxRangePx) return 'incendiary';
  if (ready('beetleSalvo') && input.salvoHasTarget) return 'beetleSalvo';
  return null;
}

/**
 * Target of the `shotIndex`-th beetle of a salvo: players and decoys in a fixed (id) order, one after
 * the other, so every one in range gets the same share even while they move. Null without any.
 */
export function pickSalvoTarget(candidates: readonly SwarmCandidate[], shotIndex: number): SwarmCandidate | null {
  const players = candidates.filter(candidate => candidate.kind === 'player')
    .sort((a, b) => a.type.localeCompare(b.type) || a.id.localeCompare(b.id));
  return players.length > 0 ? players[shotIndex % players.length] : null;
}

/** Flight time of a Brandsatz over `distancePx`, linear between the authored range ends. */
export function incendiaryFlightMs(distancePx: number, config: InfernoColossusConfig['incendiary']): number {
  const span = Math.max(1, config.maxRangePx - config.minRangePx);
  const t = Math.max(0, Math.min(1, (distancePx - config.minRangePx) / span));
  return Math.round(config.flightMinMs + (config.flightMaxMs - config.flightMinMs) * t);
}

/**
 * Landing points of a Brandsatz salvo: the main point, then pairs beside it perpendicular to the
 * throw line, `spreadPx` apart, so the fan blocks a dodge to either side.
 */
export function incendiaryLandingPoints(originX: number, originY: number, targetX: number, targetY: number,
  count: number, spreadPx: number): { x: number; y: number }[] {
  const angle = Math.atan2(targetY - originY, targetX - originX);
  const nx = -Math.sin(angle), ny = Math.cos(angle);
  const points = [{ x: targetX, y: targetY }];
  for (let i = 1; points.length < count; i++) {
    const offset = Math.ceil(i / 2) * spreadPx * (i % 2 === 1 ? 1 : -1);
    points.push({ x: targetX + nx * offset, y: targetY + ny * offset });
  }
  return points;
}

/** Free ground for the body at or near (x, y): rings of cells outward up to `searchCells`. */
export function findColossusLandingPoint(x: number, y: number, cellPx: number, searchCells: number,
  isFree: (x: number, y: number) => boolean): { x: number; y: number } | null {
  if (isFree(x, y)) return { x, y };
  for (let ring = 1; ring <= searchCells; ring++) {
    const steps = Math.max(8, ring * 8), radius = ring * cellPx;
    let best: { x: number; y: number } | null = null;
    for (let i = 0; i < steps; i++) {
      const a = i / steps * Math.PI * 2, px = x + Math.cos(a) * radius, py = y + Math.sin(a) * radius;
      if (isFree(px, py)) { best = { x: px, y: py }; break; }
    }
    if (best) return best;
  }
  return null;
}

export interface SwarmCandidate {
  /** Players and decoys share the player cap; bases the structure cap. */
  readonly kind: 'player' | 'structure';
  /** What the homing follows: a player, a decoy or a base by id. */
  readonly type: 'player' | 'decoy' | 'base';
  readonly id: string;
  readonly x: number;
  readonly y: number;
}

export type SwarmAssignment =
  | { readonly kind: 'target'; readonly target: SwarmCandidate }
  | { readonly kind: 'point'; readonly x: number; readonly y: number };

export interface SwarmShot {
  readonly angle: number;
  readonly assignment: SwarmAssignment;
}

const turnBetween = (a: number, b: number): number => {
  const d = Math.abs(((a - b) % (Math.PI * 2) + Math.PI * 3) % (Math.PI * 2) - Math.PI);
  return d;
};

/**
 * One siege wave: `count` launches spread evenly around the body (offset per wave). Each player and
 * structure takes at most its cap of the launches that need the smallest turn to reach it; every other
 * launch flies at a ground point – half of them near a player, the rest straight out from the body –
 * so the barrage covers the field without converging on one target.
 */
export function assignSwarmTargets(originX: number, originY: number, wave: number, count: number,
  candidates: readonly SwarmCandidate[], caps: { readonly perPlayer: number; readonly perStructure: number },
  seed: number, clamp: (x: number, y: number) => { x: number; y: number }): SwarmShot[] {
  const random = colossusRandom(seed);
  const step = Math.PI * 2 / count, offset = (wave % 2) * step / 2;
  const angles = Array.from({ length: count }, (_, i) => i * step + offset);
  const assigned: (SwarmAssignment | null)[] = angles.map(() => null);
  const pairs: { launch: number; candidate: number; turn: number }[] = [];
  candidates.forEach((candidate, c) => {
    const bearing = Math.atan2(candidate.y - originY, candidate.x - originX);
    angles.forEach((angle, launch) => pairs.push({ launch, candidate: c, turn: turnBetween(angle, bearing) }));
  });
  pairs.sort((a, b) => a.turn - b.turn || a.launch - b.launch || a.candidate - b.candidate);
  const used = candidates.map(() => 0);
  for (const pair of pairs) {
    const candidate = candidates[pair.candidate];
    const cap = candidate.kind === 'player' ? caps.perPlayer : caps.perStructure;
    if (assigned[pair.launch] || used[pair.candidate] >= cap) continue;
    assigned[pair.launch] = { kind: 'target', target: candidate };
    used[pair.candidate]++;
  }
  const players = candidates.filter(candidate => candidate.kind === 'player');
  let free = 0;
  return angles.map((angle, launch) => {
    const fixed = assigned[launch];
    if (fixed) return { angle, assignment: fixed };
    const nearPlayer = players.length > 0 && free++ % 2 === 0;
    let point: { x: number; y: number };
    if (nearPlayer) {
      const player = players[Math.floor(random() * players.length)];
      const a = random() * Math.PI * 2, r = 90 + random() * 130;
      point = clamp(player.x + Math.cos(a) * r, player.y + Math.sin(a) * r);
    } else {
      const r = 250 + random() * 350;
      point = clamp(originX + Math.cos(angle) * r, originY + Math.sin(angle) * r);
    }
    return { angle, assignment: { kind: 'point', x: point.x, y: point.y } };
  });
}
