import * as Phaser from 'phaser';
import { DEPTH } from '../config';
import type { SyncedCorpseMarker } from '../types';
import { CORPSE_REMAINS_TEXTURE } from './CorpseRemainsAssets';
import { ensureCanvasTexture } from './EffectUtils';

const TEX_CORPSE_ASH_STAIN = '__corpse_ash_stain';
const TEX_CORPSE_DUST_MOTE = '__corpse_dust_mote';
const STAIN_TEXTURE_SIZE = 128;
const MOTE_TEXTURE_SIZE = 24;

/** Ab dieser Kollisionsgröße liegt der große Überrest (Rippen, Schädel, breiter Haufen). */
const LARGE_BODY_SIZE = 60;
/**
 * Fläche der Überreste je Kollisionsgröße. Gewöhnliche Gegner zeichnen sich gut doppelt so groß
 * wie ihr Kollisionskreis, große Körper kaum größer; der Haufen bleibt so knapp unter dem Körper,
 * damit Knochen nicht größer wirken als der Gegner, von dem sie stammen.
 */
const FOOTPRINT_SCALE = 1.35;
const LARGE_FOOTPRINT_SCALE = 0.8;
const LARGE_FOOTPRINT_BASE = 10;
const MIN_REMAINS_WORLD_SIZE = 40;
const MAX_REMAINS_WORLD_SIZE = 400;
/** Der weiche Aschefleck reicht über den Haufen hinaus und nimmt ihm die Kante zum Boden. */
const STAIN_SCALE = 1.45;

/**
 * Die Überreste erscheinen, während der Splitter-Zerfall den farbigen Körper zu Staub auflöst:
 * zurück bleibt, was aus diesem Staub zu Boden fällt.
 */
const APPEAR_DELAY_MS = 120;
const APPEAR_MS = 460;
/** Am Ende sinken die Knochen in die Asche, danach verweht der Fleck. */
const FADE_MS = 1100;
const SINK_SCALE = 0.94;
const STAIN_ALPHA = 0.55;
const REMAINS_ALPHA = 1;
/**
 * Bodenmaterial bekommt Sonne und Grading erst über die Composites; die Blender-Werte sind auf
 * eine neutrale Vorschau abgestimmt und würden am Boden fast weiß ausbrennen.
 */
const REMAINS_TINT = 0x8c8c8c;

const REVIVE_MS = 420;
const REVIVE_SCALE = 1.08;
const REVIVE_MOTES = 18;
const REVIVE_MOTE_LIFESPAN_MS = 900;

/**
 * Leichen gehören zum Boden: über Gras, Dirt, Blut und den gebackenen Decals, aber unter Felsen,
 * Spielern, Gegnern, Projektilen und allen Effekten. Sonne, Nacht und Nebel wirken wie am Boden.
 */
const DEPTH_CORPSE_STAIN = DEPTH.GROUND_FOG + 0.09;
const DEPTH_CORPSE_REMAINS = DEPTH.GROUND_FOG + 0.1;
/** Der aufwirbelnde Staub einer Wiederbelebung steigt über die Überreste. */
const DEPTH_CORPSE_REVIVE_DUST = DEPTH.GROUND_FOG + 0.11;

interface CorpseMarkerVisual {
  readonly stain: Phaser.GameObjects.Image;
  /** Fehlt nur, wenn das Überreste-Sheet nicht geladen werden konnte. */
  readonly remains: Phaser.GameObjects.Image | null;
  readonly remainsScale: number;
  readonly stainScale: number;
  /** 0 = gerade gestorben, 1 = liegt. */
  settle: number;
  /** 0 = liegt, 1 = vergangen. */
  sink: number;
  readonly tweens: Phaser.Tweens.Tween[];
  dust: Phaser.GameObjects.Particles.ParticleEmitter | null;
}

/**
 * Zeichnet die von der Nekromantie verwertbaren Leichen als Überreste: ein Aschehaufen mit
 * Knochen und weichem Aschefleck, der am Ende der Leichenzeit in den Boden sinkt. Eine
 * Wiederbelebung wirbelt den Rest in der Farbe des Besitzers auf. Der Renderer hält keinen
 * Spielzustand: Host und Clients bekommen dieselben Ereignisse, leiten Variante und Drehung aus
 * der Leichen-ID ab und blenden die Überreste nach Ablauf der Leichenzeit selbst aus.
 */
export class CorpseMarkerRenderer {
  private readonly visuals = new Map<number, CorpseMarkerVisual>();
  /** Aufwirbelnde Reste gehören keiner Leiche mehr, müssen beim Räumen aber mit weg. */
  private readonly reviving = new Set<CorpseMarkerVisual>();

  constructor(private readonly scene: Phaser.Scene) {
    this.generateTextures();
  }

  generateTextures(): void {
    ensureCanvasTexture(this.scene.textures, TEX_CORPSE_ASH_STAIN, STAIN_TEXTURE_SIZE, STAIN_TEXTURE_SIZE, (ctx) => {
      drawAshStain(ctx);
    });
    ensureCanvasTexture(this.scene.textures, TEX_CORPSE_DUST_MOTE, MOTE_TEXTURE_SIZE, MOTE_TEXTURE_SIZE, (ctx) => {
      const center = MOTE_TEXTURE_SIZE / 2;
      const gradient = ctx.createRadialGradient(center, center, 0, center, center, center);
      gradient.addColorStop(0, 'rgba(255,255,255,1)');
      gradient.addColorStop(0.4, 'rgba(255,255,255,0.55)');
      gradient.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, MOTE_TEXTURE_SIZE, MOTE_TEXTURE_SIZE);
    });
  }

  show(corpse: SyncedCorpseMarker): void {
    const { corpseId, x, y, lifetimeMs } = corpse;
    this.remove(corpseId);
    if (lifetimeMs <= 0) return;

    const bodySize = Number.isFinite(corpse.size) && corpse.size > 0 ? corpse.size : 32;
    const footprint = Math.min(bodySize * FOOTPRINT_SCALE, bodySize * LARGE_FOOTPRINT_SCALE + LARGE_FOOTPRINT_BASE);
    const worldSize = Phaser.Math.Clamp(
      footprint / CORPSE_REMAINS_TEXTURE.footprintShare,
      MIN_REMAINS_WORLD_SIZE,
      MAX_REMAINS_WORLD_SIZE,
    );
    const hash = corpseHash(corpseId);
    // Liegende Überreste haben keine Blickrichtung: jede Drehung ist gleich richtig.
    const rotation = (hash % 3600) / 3600 * Math.PI * 2;
    const frames = bodySize >= LARGE_BODY_SIZE ? CORPSE_REMAINS_TEXTURE.largeFrames : CORPSE_REMAINS_TEXTURE.smallFrames;
    const frame = frames[(hash >>> 12) % frames.length];

    const stainScale = (worldSize * CORPSE_REMAINS_TEXTURE.footprintShare * STAIN_SCALE) / STAIN_TEXTURE_SIZE;
    const stain = this.scene.add.image(x, y, TEX_CORPSE_ASH_STAIN)
      .setDepth(DEPTH_CORPSE_STAIN)
      .setRotation(rotation * 1.7)
      .setAlpha(0);

    let remains: Phaser.GameObjects.Image | null = null;
    if (this.scene.textures.exists(CORPSE_REMAINS_TEXTURE.key)) {
      remains = this.scene.add.image(x, y, CORPSE_REMAINS_TEXTURE.key, frame)
        .setDepth(DEPTH_CORPSE_REMAINS)
        .setRotation(rotation)
        .setTint(REMAINS_TINT)
        .setAlpha(0);
    }

    const visual: CorpseMarkerVisual = {
      stain,
      remains,
      remainsScale: worldSize / CORPSE_REMAINS_TEXTURE.frame.frameWidth,
      stainScale,
      settle: 0,
      sink: 0,
      tweens: [],
      dust: null,
    };
    this.visuals.set(corpseId, visual);
    applyLying(visual);

    const fadeMs = Math.min(FADE_MS, lifetimeMs);
    const appearDelayMs = Math.min(APPEAR_DELAY_MS, Math.max(0, lifetimeMs - fadeMs));
    const holdMs = Math.max(appearDelayMs, lifetimeMs - fadeMs);
    visual.tweens.push(this.scene.tweens.addCounter({
      from: 0,
      to: 1,
      delay: appearDelayMs,
      duration: APPEAR_MS,
      ease: 'Sine.easeOut',
      onUpdate: (tween) => {
        visual.settle = tween.getValue() ?? 1;
        applyLying(visual);
      },
    }));
    visual.tweens.push(this.scene.tweens.addCounter({
      from: 0,
      to: 1,
      delay: holdMs,
      duration: fadeMs,
      ease: 'Sine.easeIn',
      onUpdate: (tween) => {
        visual.settle = 1;
        visual.sink = tween.getValue() ?? 1;
        applyLying(visual);
      },
      onComplete: () => {
        if (this.visuals.get(corpseId) !== visual) return;
        this.visuals.delete(corpseId);
        destroyVisual(visual);
      },
    }));
  }

  /**
   * Entfernt die Überreste. Mit `revivedColor` wirbelt der Rest in der Farbe des Besitzers auf,
   * während an seiner Stelle der Verbündete erscheint; ohne Farbe (Räumen) verschwindet er sofort.
   */
  remove(corpseId: number, revivedColor?: number): void {
    const visual = this.visuals.get(corpseId);
    if (!visual) return;
    this.visuals.delete(corpseId);
    if (revivedColor === undefined) {
      destroyVisual(visual);
      return;
    }
    this.playRevive(visual, revivedColor);
  }

  clearAll(): void {
    for (const corpseId of [...this.visuals.keys()]) this.remove(corpseId);
    for (const visual of this.reviving) destroyVisual(visual);
    this.reviving.clear();
  }

  destroy(): void {
    this.clearAll();
  }

  private playRevive(visual: CorpseMarkerVisual, revivedColor: number): void {
    const { remains, stain } = visual;
    stopTweens(visual);
    this.reviving.add(visual);
    const glow = Phaser.Display.Color.ValueToColor(revivedColor).lighten(18).color;
    const reach = visual.remainsScale * CORPSE_REMAINS_TEXTURE.frame.frameWidth * CORPSE_REMAINS_TEXTURE.footprintShare;
    const dust = this.scene.add.particles(stain.x, stain.y, TEX_CORPSE_DUST_MOTE, {
      emitting: false,
      lifespan: { min: REVIVE_MOTE_LIFESPAN_MS * 0.55, max: REVIVE_MOTE_LIFESPAN_MS },
      speed: { min: reach * 0.25, max: reach * 0.9 },
      angle: { min: 0, max: 360 },
      scale: { start: reach / 260, end: reach / 70 },
      alpha: { start: 0.7, end: 0 },
      tint: [glow, revivedColor, 0x9a9087],
      emitZone: { type: 'random', source: new Phaser.Geom.Circle(0, 0, reach * 0.35), quantity: REVIVE_MOTES },
    });
    dust.setDepth(DEPTH_CORPSE_REVIVE_DUST);
    dust.explode(REVIVE_MOTES);
    visual.dust = dust;

    const startRemains = remains?.alpha ?? 0;
    const startStain = stain.alpha;
    remains?.setTint(glow);
    visual.tweens.push(this.scene.tweens.addCounter({
      from: 0,
      to: 1,
      duration: REVIVE_MS,
      ease: 'Quad.easeOut',
      onUpdate: (tween) => {
        const t = tween.getValue() ?? 1;
        // Der Rest hellt in Besitzerfarbe auf, hebt sich ein Stück und zerstäubt.
        remains?.setAlpha(startRemains * (1 - t))
          .setScale(visual.remainsScale * (1 + (REVIVE_SCALE - 1) * t));
        stain.setAlpha(startStain * (1 - t));
      },
    }));
    visual.tweens.push(this.scene.tweens.addCounter({
      from: 0,
      to: 1,
      duration: REVIVE_MOTE_LIFESPAN_MS,
      onComplete: () => {
        this.reviving.delete(visual);
        destroyVisual(visual);
      },
    }));
  }
}

function applyLying(visual: CorpseMarkerVisual): void {
  const { settle, sink, remains, stain } = visual;
  // Asche sammelt sich: der Haufen setzt sich etwas größer ab und schrumpft beim Einsinken.
  const gather = 0.9 + 0.1 * settle;
  const sunk = 1 + (SINK_SCALE - 1) * sink;
  // Knochen vergehen vor ihrem Aschefleck: so wirkt das Ende wie Einsinken und Verwehen.
  remains?.setAlpha(REMAINS_ALPHA * settle * Math.max(0, 1 - sink * 1.4))
    .setScale(visual.remainsScale * gather * sunk);
  stain.setAlpha(STAIN_ALPHA * settle * (1 - sink))
    .setScale(visual.stainScale * (0.7 + 0.3 * settle));
}

function stopTweens(visual: CorpseMarkerVisual): void {
  for (const tween of visual.tweens) tween.remove();
  visual.tweens.length = 0;
}

function destroyVisual(visual: CorpseMarkerVisual): void {
  stopTweens(visual);
  visual.stain.destroy();
  visual.remains?.destroy();
  visual.dust?.destroy();
  visual.dust = null;
}

/** Ganzzahliger Mischwert der Leichen-ID; Host und Clients wählen damit dieselbe Variante. */
function corpseHash(corpseId: number): number {
  let h = Math.imul(corpseId ^ 0x9e3779b9, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  return (h ^ (h >>> 16)) >>> 0;
}

/** Unregelmäßiger, weich auslaufender Aschefleck aus überlagerten Flecken. */
function drawAshStain(ctx: CanvasRenderingContext2D): void {
  const center = STAIN_TEXTURE_SIZE / 2;
  let seed = 0x2f6b1d;
  const random = (): number => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed / 4294967296;
  };
  const blot = (x: number, y: number, radius: number, alpha: number): void => {
    const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
    gradient.addColorStop(0, `rgba(24,20,17,${alpha})`);
    gradient.addColorStop(0.55, `rgba(30,25,21,${alpha * 0.55})`);
    gradient.addColorStop(1, 'rgba(34,28,24,0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
  };
  blot(center, center, center * 0.72, 0.7);
  for (let i = 0; i < 9; i += 1) {
    const angle = random() * Math.PI * 2;
    const distance = center * (0.18 + random() * 0.38);
    blot(center + Math.cos(angle) * distance, center + Math.sin(angle) * distance, center * (0.22 + random() * 0.24), 0.32 + random() * 0.25);
  }
  // Feine Ascheflocken im Randbereich brechen die runde Form auf.
  for (let i = 0; i < 70; i += 1) {
    const angle = random() * Math.PI * 2;
    const distance = center * (0.35 + random() * 0.55);
    const radius = 0.8 + random() * 2.2;
    ctx.fillStyle = `rgba(26,22,19,${0.25 + random() * 0.4})`;
    ctx.beginPath();
    ctx.arc(center + Math.cos(angle) * distance, center + Math.sin(angle) * distance, radius, 0, Math.PI * 2);
    ctx.fill();
  }
}
